from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

def sign_v1a(private_key: Ed25519PrivateKey, msg_id: str, ts: int, body: bytes) -> str:
    sig = private_key.sign(f"{msg_id}.{ts}.".encode() + body)
    return "v1a," + base64.b64encode(sig).decode()

