async def acquire(self, endpoint_id: str, per_second: float) -> int:
    """0 = go ahead, otherwise milliseconds to wait. Fails OPEN on Redis errors..."""
    burst = max(1.0, per_second)
    try:
        return int(await self._script(keys=[f"wh:rl:{endpoint_id}"], args=[burst, per_second]))
    except RedisError:
        return 0

# real: webhooks/dispatcher/dispatcher.py
async def run(self, idle_sleep: float = 0.5) -> None:
    backoff = idle_sleep
    while not self._stop.is_set():
        try:
            n = await self.run_once()
            backoff = idle_sleep
        except Exception:
            # Postgres restart / network blip: log and retry with backoff instead of exiting the process.
            log.exception("dispatch_loop_error")
            n = 0
            backoff = min(backoff * 2, 30.0)
        if n == 0:
            try:
                await asyncio.wait_for(self._stop.wait(), timeout=backoff)
            except asyncio.TimeoutError:
                pass

